SELECT toDate(timestamp) AS Day, uniqExactIf(properties.installation_id,event='native_first_observed') AS First_observed,uniqExactIf(properties.installation_id,event IN ('native_app_opened','native_app_active')) AS Active_installations FROM events WHERE event IN ('native_first_observed','native_app_opened','native_app_active') AND (properties.environment = 'production' AND properties.product = 'studio') AND {filters} GROUP BY Day ORDER BY Day LIMIT 1000
